from pathlib import Path

root=Path('/mnt/data/work160403')
menu=root/'src/components/ui/MeshMenu.jsx'
css=root/'src/components/ui/MeshMenu.css'
land=root/'src/components/world/Landscape.jsx'

s=menu.read_text()
# Add profiles selector next to selected profile.
s=s.replace('''  const scatterProfile = useWorldStore(\n    (state) => selectedMesh?.id ? state.world.scatterProfiles?.[selectedMesh.id] : null\n  );\n''','''  const scatterProfiles = useWorldStore((state) => state.world.scatterProfiles ?? {});\n  const scatterProfile = useWorldStore(\n    (state) => selectedMesh?.id ? state.world.scatterProfiles?.[selectedMesh.id] : null\n  );\n''')

# Replace add/update/remove functions with population-aware versions.
start=s.index('function addToScatter() {')
end=s.index('\n  useEffect(() => {\n    function handleEscape', start)
new='''function getDefaultCrimsonProfile() {\n  const current = useWorldStore.getState().world.scatterProfiles?.["crimson-tree"];\n  return {\n    enabled: current?.enabled !== false,\n    objectId: "crimson-tree",\n    name: "CRIMSON TREE",\n    kind: "tree",\n    source: "procedural",\n    modelType: "crimson-tree",\n    treeDefinition: current?.treeDefinition ?? createCrimsonTreeDefinition(),\n    density: Number(current?.density ?? 25),\n    coverage: Number(current?.coverage ?? 50),\n    scaleVariation: Number(current?.scaleVariation ?? 25),\n    rotationVariation: Number(current?.rotationVariation ?? 100),\n    clustering: Number(current?.clustering ?? 35),\n  };\n}\n\n  function addToScatter() {\n    if (!selectedMesh) return;\n\n    useInteractionStore.getState().activate({\n      target: `object:${selectedMesh.id}`,\n      tool: "SCATTER",\n      mode: "EDIT",\n    });\n\n    window.dispatchEvent(\n      new CustomEvent("tg-mesh-cancel-placement")\n    );\n\n    const worldStore = useWorldStore.getState();\n    worldStore.upsertScatterProfile(selectedMesh.id, {\n      enabled: true,\n      objectId: selectedMesh.id,\n      name: selectedMesh.name,\n      kind: selectedMesh.kind,\n      source: selectedMesh.source,\n      modelPath: selectedMesh.modelPath,\n      modelType: selectedMesh.modelType,\n      geologyType: selectedMesh.geologyType,\n      treeDefinition: selectedMesh.treeDefinition ?? (selectedMesh.modelType === "crimson-tree" ? createCrimsonTreeDefinition() : undefined),\n      density: Number(scatterProfile?.density ?? 50),\n      coverage: Number(scatterProfile?.coverage ?? 50),\n      width: Number(scatterProfile?.width ?? (selectedMesh.geologyType === "canyon-wall" ? 60 : 36)),\n      height: Number(scatterProfile?.height ?? (selectedMesh.geologyType === "canyon-wall" ? 30 : 12)),\n      scaleVariation: Number(scatterProfile?.scaleVariation ?? 25),\n      rotationVariation: Number(scatterProfile?.rotationVariation ?? 100),\n      clustering: Number(scatterProfile?.clustering ?? 35),\n    });\n\n    setMode("scatter");\n\n    window.dispatchEvent(\n      new CustomEvent("tg-mesh-scatter-request", {\n        detail: { mesh: selectedMesh },\n      })\n    );\n  }\n\n  function updateScatterSetting(profileId, key, value) {\n    if (!profileId) return;\n    const current = useWorldStore.getState().world.scatterProfiles?.[profileId] ??\n      (profileId === "crimson-tree" ? getDefaultCrimsonProfile() : null);\n    if (!current) return;\n\n    useWorldStore.getState().upsertScatterProfile(profileId, {\n      ...current,\n      objectId: profileId,\n      enabled: true,\n      [key]: Number(value),\n    });\n  }\n\n  function selectScatterPopulation(profileId) {\n    const mesh = meshes.find((entry) => entry.id === profileId);\n    if (!mesh) return;\n    setSelectedId(profileId);\n    setMode("scatter");\n    setEditOpen(false);\n    useInteractionStore.getState().clear();\n  }\n\n  function removeScatterPopulation(profileId) {\n    if (!profileId) return;\n    if (profileId === "crimson-tree") {\n      const current = useWorldStore.getState().world.scatterProfiles?.[profileId] ?? getDefaultCrimsonProfile();\n      useWorldStore.getState().upsertScatterProfile(profileId, {\n        ...current,\n        objectId: "crimson-tree",\n        enabled: false,\n      });\n      if (selectedId === profileId) useInteractionStore.getState().clear();\n      return;\n    }\n\n    useWorldStore.getState().removeScatterProfile(profileId);\n    if (selectedId === profileId) {\n      useInteractionStore.getState().clear();\n      setSelectedId(null);\n    }\n  }\n\n  function enableScatterPopulation(profileId) {\n    if (!profileId) return;\n    const current = useWorldStore.getState().world.scatterProfiles?.[profileId];\n    if (!current) return;\n    useWorldStore.getState().upsertScatterProfile(profileId, { ...current, enabled: true });\n  }\n\n  function scatterEntries() {\n    const defaultProfile = scatterProfiles["crimson-tree"] ?? getDefaultCrimsonProfile();\n    const custom = Object.entries(scatterProfiles)\n      .filter(([id, profile]) => id !== "crimson-tree" && profile?.enabled)\n      .map(([id, profile]) => [id, profile]);\n    return [["crimson-tree", defaultProfile], ...custom];\n  }\n'''
s=s[:start]+new+s[end:]

# Replace action button label behavior slightly: scatter manager always opens if enabled; default disabled can add.
s=s.replace('''          <button type="button" className={scatterProfile?.enabled ? "active" : ""} onClick={scatterProfile?.enabled ? () => setMode("scatter") : addToScatter}>\n            {scatterProfile?.enabled ? "SCATTER" : "ADD TO SCATTER"}\n          </button>''','''          <button type="button" className={mode === "scatter" ? "active" : ""} onClick={scatterProfile?.enabled ? () => setMode("scatter") : addToScatter}>\n            {scatterProfile?.enabled ? "SCATTER" : "ADD TO SCATTER"}\n          </button>''')

old='''        {scatterProfile?.enabled && (\n          <div className="tg-mesh-scatter-panel">\n            <div className="tg-mesh-scatter-heading">\n              <span>SCATTER</span>\n              <strong>{selectedMesh?.name ?? "OBJECT"}</strong>\n            </div>\n            <label className="tg-mesh-scatter-slider">\n              <span>DENSITY <strong>{Number(scatterProfile.density ?? 50)}</strong></span>\n              <input type="range" min="0" max="100" value={Number(scatterProfile.density ?? 50)} onChange={(event) => updateScatterSetting("density", event.target.value)} />\n            </label>\n            <label className="tg-mesh-scatter-slider">\n              <span>COVERAGE <strong>{Number(scatterProfile.coverage ?? 50)}</strong></span>\n              <input type="range" min="0" max="100" value={Number(scatterProfile.coverage ?? 50)} onChange={(event) => updateScatterSetting("coverage", event.target.value)} />\n            </label>\n            <button type="button" className="tg-mesh-scatter-remove" onClick={removeFromScatter}>REMOVE FROM SCATTER</button>\n          </div>\n        )}'''
newpanel='''        {mode === "scatter" && (\n          <div className="tg-mesh-scatter-panel tg-mesh-scatter-manager">\n            <div className="tg-mesh-scatter-manager-title">SCATTER</div>\n            <div className="tg-mesh-scatter-manager-scroll">\n              {scatterEntries().map(([profileId, profile]) => {\n                const isDefault = profileId === "crimson-tree";\n                const isEnabled = profile?.enabled !== false;\n                const isSelected = selectedId === profileId;\n                const isCanyonWall = profile?.geologyType === "canyon-wall" || profile?.modelType === "geology";\n                return (\n                  <div key={profileId} className={`tg-scatter-population ${isSelected ? "selected" : ""} ${!isEnabled ? "disabled" : ""}`}>\n                    <button type="button" className="tg-scatter-population-header" onClick={() => selectScatterPopulation(profileId)}>\n                      <span>{profile?.name ?? profileId}</span>\n                      <strong>{isDefault ? "DEFAULT" : "CUSTOM"}</strong>\n                    </button>\n\n                    {isEnabled && (\n                      <>\n                        {isCanyonWall ? (\n                          <>\n                            <label className="tg-mesh-scatter-slider">\n                              <span>WIDTH <strong>{Number(profile?.width ?? 60)}</strong></span>\n                              <input type="range" min="5" max="120" value={Number(profile?.width ?? 60)} onChange={(event) => updateScatterSetting(profileId, "width", event.target.value)} />\n                            </label>\n                            <label className="tg-mesh-scatter-slider">\n                              <span>HEIGHT <strong>{Number(profile?.height ?? 30)}</strong></span>\n                              <input type="range" min="2" max="80" value={Number(profile?.height ?? 30)} onChange={(event) => updateScatterSetting(profileId, "height", event.target.value)} />\n                            </label>\n                          </>\n                        ) : (\n                          <>\n                            <label className="tg-mesh-scatter-slider">\n                              <span>DENSITY <strong>{Number(profile?.density ?? 50)}</strong></span>\n                              <input type="range" min="0" max="100" value={Number(profile?.density ?? 50)} onChange={(event) => updateScatterSetting(profileId, "density", event.target.value)} />\n                            </label>\n                            <label className="tg-mesh-scatter-slider">\n                              <span>COVERAGE <strong>{Number(profile?.coverage ?? 50)}</strong></span>\n                              <input type="range" min="0" max="100" value={Number(profile?.coverage ?? 50)} onChange={(event) => updateScatterSetting(profileId, "coverage", event.target.value)} />\n                            </label>\n                          </>\n                        )}\n                        <button type="button" className="tg-mesh-scatter-remove" onClick={() => removeScatterPopulation(profileId)}>\n                          REMOVE\n                        </button>\n                      </>\n                    )}\n\n                    {!isEnabled && (\n                      <button type="button" className="tg-mesh-scatter-enable" onClick={() => enableScatterPopulation(profileId)}>ENABLE</button>\n                    )}\n                  </div>\n                );\n              })}\n            </div>\n            {selectedMesh && !scatterProfiles[selectedMesh.id]?.enabled && selectedMesh.id !== "crimson-tree" && (\n              <button type="button" className="tg-mesh-scatter-add-selected" onClick={addToScatter}>ADD SELECTED TO SCATTER</button>\n            )}\n          </div>\n        )}'''
if old not in s:
    raise SystemExit('old scatter panel not found')
s=s.replace(old,newpanel)

menu.write_text(s)

# CSS replace scatter controls block with manager styles while retaining slider rules.
c=css.read_text()
start=c.index('/* =======================================================\n   Scatter Controls')
end=c.index('\n\n.tg-mesh-card-delete', start)
newcss='''/* =======================================================\n   Scatter Population Manager\n======================================================= */\n.tg-mesh-scatter-panel {\n  width: 250px;\n  flex: 0 0 250px;\n  min-width: 0;\n  padding: 7px 8px;\n  border-left: 1px solid rgba(205, 38, 38, 0.35);\n  border-right: 1px solid rgba(205, 38, 38, 0.35);\n  background: rgba(5, 6, 8, 0.48);\n  display: flex;\n  flex-direction: column;\n  gap: 7px;\n  box-sizing: border-box;\n}\n\n.tg-mesh-scatter-manager-title {\n  color: var(--tg-white);\n  font-family: var(--tg-font-display);\n  font-size: 13px;\n  letter-spacing: 0.08em;\n}\n\n.tg-mesh-scatter-manager-scroll {\n  min-height: 0;\n  max-height: 270px;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 7px;\n  padding-right: 3px;\n}\n\n.tg-scatter-population {\n  border: 1px solid rgba(205, 38, 38, 0.42);\n  background: rgba(8, 10, 14, 0.74);\n  padding: 7px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.tg-scatter-population.selected {\n  border-color: rgba(205, 38, 38, 0.78);\n}\n\n.tg-scatter-population.disabled {\n  opacity: 0.68;\n}\n\n.tg-scatter-population-header {\n  width: 100%;\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 8px;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--tg-white);\n  text-align: left;\n  font-family: var(--tg-font-display);\n  cursor: pointer;\n}\n\n.tg-scatter-population-header span {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-size: 12px;\n  letter-spacing: 0.055em;\n}\n\n.tg-scatter-population-header strong {\n  flex: 0 0 auto;\n  color: rgba(232, 238, 245, 0.48);\n  font-size: 9px;\n  letter-spacing: 0.08em;\n  font-weight: 400;\n}\n\n.tg-mesh-scatter-slider {\n  display: grid;\n  gap: 3px;\n  font-family: var(--tg-font-copy);\n  font-size: 10px;\n  color: rgba(232, 238, 245, 0.72);\n}\n\n.tg-mesh-scatter-slider span {\n  display: flex;\n  justify-content: space-between;\n  letter-spacing: 0.06em;\n}\n\n.tg-mesh-scatter-slider strong {\n  color: var(--tg-white);\n  font-weight: 500;\n}\n\n.tg-mesh-scatter-slider input {\n  width: 100%;\n  accent-color: var(--tg-crimson);\n}\n\n.tg-mesh-scatter-remove,\n.tg-mesh-scatter-enable,\n.tg-mesh-scatter-add-selected {\n  min-height: 27px;\n  border: 1px solid rgba(205, 38, 38, 0.72);\n  background: rgba(5, 6, 8, 0.72);\n  color: var(--tg-white);\n  font-family: var(--tg-font-display);\n  font-size: 10px;\n  letter-spacing: 0.07em;\n  cursor: pointer;\n}\n\n.tg-mesh-scatter-remove:hover,\n.tg-mesh-scatter-enable:hover,\n.tg-mesh-scatter-add-selected:hover {\n  background: linear-gradient(90deg, var(--tg-maroon), var(--tg-crimson));\n}\n\n.tg-mesh-scatter-add-selected {\n  margin-top: auto;\n}\n'''
c=c[:start]+newcss+c[end:]
css.write_text(c)

# Landscape: custom procedural trees never receive the legacy Crimson crown.
l=land.read_text()
l=l.replace('legacyCrown={!profile?.treeDefinition || isDefaultCrimson}', 'legacyCrown={isDefaultCrimson}')
# Default crimson profile should be truly removable/disable-able.
old='''    const entries = [];\n    const defaultProfile = profiles["crimson-tree"];\n    entries.push([\n      "crimson-tree",\n      defaultProfile?.enabled\n        ? defaultProfile\n        : {\n            enabled: true,\n            density: treeDensityFallback,\n            coverage: treeCoverageFallback,\n            modelType: "crimson-tree",\n          },\n    ]);'''
new='''    const entries = [];\n    const defaultProfile = profiles["crimson-tree"];\n    if (defaultProfile?.enabled !== false) {\n      entries.push([\n        "crimson-tree",\n        defaultProfile ?? {\n          enabled: true,\n          density: treeDensityFallback,\n          coverage: treeCoverageFallback,\n          modelType: "crimson-tree",\n        },\n      ]);\n    }'''
if old not in l:
    raise SystemExit('default profile block not found')
l=l.replace(old,new)
land.write_text(l)

# Patch notes
notes=root/'PATCH_NOTES_1.6.04.03.md'
notes.write_text('''# Testing Grounds 1.6.04.03\n\n## Scatter Population Architecture\n\n### Custom procedural tree canopy\n- Custom procedural Crimson Tree-derived scatter profiles no longer receive the legacy Crimson canopy.\n- The saved `treeDefinition` is authoritative for custom tree canopy generation.\n- The legacy canopy is reserved for the default Crimson Tree population.\n\n### Scatter menu\n- Scatter is now a population manager rather than a panel for only the selected object.\n- Default `CRIMSON TREE` appears first and is labeled `DEFAULT`.\n- Custom scatter profiles appear underneath and are labeled `CUSTOM`.\n- Tree populations expose `DENSITY` and `COVERAGE`.\n- Canyon Wall / geology profiles expose `WIDTH` and `HEIGHT`.\n- Each population has its own `REMOVE` action.\n- Removing a custom population removes its scatter profile but does not delete the source object.\n- Removing the default Crimson Tree disables its default population while retaining its settings; `ENABLE` restores it.\n- Multiple custom populations can coexist.\n- Selecting a population from the manager selects it for scatter editing without entering Place mode.\n- The selected object can be added to Scatter directly from the manager.\n\n### Persistence / scope\n- Existing 1.6.04.02 single-tree vs all-scattered tree editing scope is preserved.\n- No scatter performance optimization is included; the generation hitch remains bookmarked for the future 1.8/1.9 rendering optimization pass.\n\n## Verification\n- JSX delimiter sanity checks and JavaScript syntax checks should be run locally before runtime testing.\n- ZIP integrity verified after packaging.\n''')

print('patched')
